-- Los vínculos previos no se admiten ni se asignan por migración.
ALTER TABLE core_link ADD COLUMN requirement_reference VARCHAR(36) NULL;
ALTER TABLE core_link ADD COLUMN revision BIGINT NOT NULL DEFAULT 0;
ALTER TABLE core_link ADD FOREIGN KEY(requirement_reference) REFERENCES core_requirement(id);
CREATE TABLE core_link_evaluation(child_id VARCHAR(36) PRIMARY KEY,decision VARCHAR(20) NOT NULL,reason_text VARCHAR(2000) NOT NULL,actor_id VARCHAR(64) NOT NULL,at_ms BIGINT NOT NULL,case_revision BIGINT NOT NULL,FOREIGN KEY(child_id) REFERENCES core_link(child_id),FOREIGN KEY(actor_id) REFERENCES core_actor(id),CHECK(decision IN ('ADMITIDA','NO_ADMITIDA')));
CREATE TABLE core_reopen(id VARCHAR(36) PRIMARY KEY,case_id VARCHAR(36) NOT NULL,requested_by VARCHAR(64) NOT NULL,requested_ms BIGINT NOT NULL,case_revision BIGINT NOT NULL,closed_ms BIGINT NOT NULL,closed_by VARCHAR(64),closure_mode VARCHAR(32),reason_text VARCHAR(2000) NOT NULL,state VARCHAR(16) NOT NULL,revision BIGINT NOT NULL,decided_by VARCHAR(64),decided_ms BIGINT,decision_text VARCHAR(2000),supersedes_id VARCHAR(36),FOREIGN KEY(case_id) REFERENCES core_case(id),FOREIGN KEY(requested_by) REFERENCES core_actor(id),FOREIGN KEY(decided_by) REFERENCES core_actor(id),FOREIGN KEY(supersedes_id) REFERENCES core_reopen(id),CHECK(state IN ('PENDIENTE','APROBADA','RECHAZADA','SUPERADA')));
CREATE INDEX ix_reopen_case_state ON core_reopen(case_id,state);
CREATE TABLE core_reopen_evidence(request_id VARCHAR(36) NOT NULL,child_id VARCHAR(36) NOT NULL,link_revision BIGINT NOT NULL,PRIMARY KEY(request_id,child_id),FOREIGN KEY(request_id) REFERENCES core_reopen(id),FOREIGN KEY(child_id) REFERENCES core_link_evaluation(child_id));
CREATE TABLE core_management_period(id VARCHAR(36) PRIMARY KEY,case_id VARCHAR(36) NOT NULL,request_id VARCHAR(36) NOT NULL UNIQUE,opened_ms BIGINT NOT NULL,authorized_by VARCHAR(64) NOT NULL,FOREIGN KEY(case_id) REFERENCES core_case(id),FOREIGN KEY(request_id) REFERENCES core_reopen(id),FOREIGN KEY(authorized_by) REFERENCES core_actor(id));
